CREATE OR REPLACE FUNCTION public.account_erasure_scrub_payment(p_profile_id uuid, p_table text, p_limit integer DEFAULT 100, p_after_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
